from __future__ import annotations
from functools import reduce
from math import gcd

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n): a, b = b, a + b
    return a

def gcd_all(xs: list[int]) -> int:
    return reduce(gcd, xs, 0)

def synchronized(q: int, p: int, indices: list[int]) -> bool:
    index_side = gcd_all(indices) % q == 0
    value_side = gcd_all([fib(n) for n in indices]) % p == 0
    return index_side == value_side

for s in ([], [26, 39, 65], [26, 39, 66], [0, 26, 52]):
    print(s, synchronized(13, 233, s))

